use vstd::prelude::*;

verus! {
    fn list_deep_clone(arr: &Vec<u64>) -> (copied: Vec<u64>)
        requires
            arr.len() <= u64::MAX as usize, // Ensure the length of the array is within bounds
        ensures
            copied.len() == arr.len() && // The output array has the same length as the input
            forall|i: nat| (i < arr.len() as nat) ==> (copied[i] == arr[i]), // Each element is copied correctly
            // The copied array is independent of the input array
            forall|i: nat| (i < arr.len() as nat) ==> (copied[i] == arr[i]) && (arr[i] == arr[i]), // No aliasing
    {
        let mut copied: Vec<u64> = Vec::new(); // Initialize the copied vector
        let len = arr.len(); // Get the length of the input array
        let mut idx: usize = 0; // Initialize the index for iteration

        while idx < len
            invariant
                idx <= len, // Ensure the index does not exceed the length
                copied.len() == idx, // The length of copied matches the index
                forall|i: nat| (i < idx as nat) ==> (copied[i] == arr[i]), // Ensure copied elements match
            decreases len - idx, // Decrease clause for termination
        {
            copied.push(arr[idx]); // Copy the element from arr to copied
            idx = idx + 1; // Increment the index
        }

        copied // Return the copied vector
    }
}

